package edu.exam;
import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.web.*;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.filter.OncePerRequestFilter;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.util.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import com.fasterxml.jackson.databind.ObjectMapper;
@Configuration public class Security {
 @Bean BCryptPasswordEncoder encoder(){return new BCryptPasswordEncoder();}
 @Bean SecurityFilterChain chain(HttpSecurity h,Store db,@Value("${exam.jwt-secret}") String secret,@Value("${exam.origin}") String origin)throws Exception {if(secret.length()<32)throw new IllegalArgumentException("JWT_SECRET needs 32 characters");return h.csrf(c->c.disable()).cors(c->c.configurationSource(r->{var x=new org.springframework.web.cors.CorsConfiguration();x.setAllowedOrigins(List.of(origin));x.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));x.setAllowedHeaders(List.of("Authorization","Content-Type"));return x;})).sessionManagement(c->c.sessionCreationPolicy(org.springframework.security.config.http.SessionCreationPolicy.STATELESS)).authorizeHttpRequests(c->c.requestMatchers("/api/v1/auth/login","/api/v1/health","/swagger-ui/**","/v3/api-docs/**").permitAll().requestMatchers("/api/v1/admin/**").hasRole("ADMIN").requestMatchers("/api/v1/faculty/**").hasRole("FACULTY").requestMatchers("/api/v1/student/**").hasRole("STUDENT").anyRequest().authenticated()).exceptionHandling(c->c.accessDeniedHandler((r,s,e)->{s.setStatus(403);s.setContentType("application/json");s.getWriter().write("{\"message\":\"Permission denied\"}");}).authenticationEntryPoint((r,s,e)->{s.setStatus(401);s.setContentType("application/json");s.getWriter().write("{\"message\":\"Authentication required\"}");})).addFilterBefore(new OncePerRequestFilter(){protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws java.io.IOException,ServletException {try{String a=r.getHeader("Authorization");if(a!=null&&a.startsWith("Bearer ")){String[] parts=a.substring(7).split("\\.");if(parts.length!=3||!java.security.MessageDigest.isEqual(sign(parts[0]+"."+parts[1],secret).getBytes(),parts[2].getBytes()))throw new Exception();var payload=new ObjectMapper().readTree(Base64.getUrlDecoder().decode(parts[1]));if(payload.get("exp").asLong()<System.currentTimeMillis()/1000)throw new Exception();var u=db.one("SELECT user_id,role FROM users WHERE user_id=? AND is_active=1",payload.get("sub").asLong());SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.get("user_id").toString(),null,List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_"+u.get("role")))));}}catch(Exception ignored){SecurityContextHolder.clearContext();}c.doFilter(r,s);}},UsernamePasswordAuthenticationFilter.class).build();}
 static String sign(String data,String secret)throws Exception {Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(data.getBytes()));}
 static String token(long id,String secret)throws Exception {var b=Base64.getUrlEncoder().withoutPadding();String v=b.encodeToString("{\"alg\":\"HS256\",\"typ\":\"JWT\"}".getBytes())+"."+b.encodeToString(("{\"sub\":\""+id+"\",\"exp\":"+(System.currentTimeMillis()/1000+3600)+"}").getBytes());return v+"."+sign(v,secret);}
}
